mapper.select:
SELECT o.id, o.order_no, o.user_id, o.screening_id, o.movie_id, o.status, o.total_amount, o.pay_expire_time, o.pay_time, o.create_time, o.update_time, u.phone AS user_phone, m.title AS movie_title FROM t_order o LEFT JOIN t_user u ON u.id = o.user_id LEFT JOIN t_movie m ON m.id = o.movie_id
AND o.order_no = #{orderNo}
AND o.status = #{status}
AND o.cinema_id = #{cinemaId}
ORDER BY o.create_time DESC
